        load_full(xn, vn_off);
        load_full(xm, vm_off);
        as_.Pand(xn, xm);
        as_.Pxor(xm, xm);  // xm = 0.
        switch (args.size) {
          case 0b00: as_.Pcmpeqb(xn, xm); break;
          case 0b01: as_.Pcmpeqw(xn, xm); break;
          case 0b10: as_.Pcmpeqd(xn, xm); break;
          case 0b11: as_.Pcmpeqq(xn, xm); break;
          default: Undefined(); return;
        }
